# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def make_student(last, first, email="x@y.org"):
    return Student("1", last, first, "A", email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = format_contacts([
            make_student("Zed", "Amy", "z@y.org"),
            make_student("Long", "Bob", "l@y.org")
        ])
        self.assertEqual(rows, [
            "Long, Bob  A  l@y.org",
            "Zed, Amy   A  z@y.org"
        ])

    def test_missing_email_names_student(self):
        bad = make_student("Kim", "Lee", None)
        with self.assertRaisesRegex(ProjectError, "Kim, Lee"):
            format_contacts([bad])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            format_contacts([])


if __name__ == "__main__":
    unittest.main()
